using System.Security.Claims; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace JuvicClinic.Api.Features.Treatments;
[Authorize(Roles="ADMIN,DOCTOR,NURSE"),ApiController,Route("api/treatments")]
public sealed class TreatmentsController(TreatmentsService service):ControllerBase{private bool UserId(out Guid id)=>Guid.TryParse(User.FindFirstValue(ClaimTypes.NameIdentifier),out id);[Authorize(Roles="ADMIN,DOCTOR"),HttpPost("visits/{visitId:guid}/plans")]public async Task<IActionResult>Create(Guid visitId,CreateTreatmentPlanRequest input,CancellationToken ct){if(!UserId(out var userId))return Unauthorized();try{return Created("",await service.CreatePlanAsync(visitId,input,userId,ct));}catch(ArgumentException ex){return BadRequest(new{message=ex.Message});}}[HttpGet("due")]public Task<object>Due(string scope="due",CancellationToken ct=default)=>service.DueAsync(scope,ct);[HttpPost("doses/{id:guid}/administer")]public async Task<IActionResult>Administer(Guid id,AdministerDoseRequest input,CancellationToken ct){if(!UserId(out var userId))return Unauthorized();try{return await service.AdministerAsync(id,input,userId,ct)?NoContent():NotFound();}catch(InvalidOperationException ex){return Conflict(new{message=ex.Message});}}[HttpPost("doses/{id:guid}/miss")]public async Task<IActionResult>Miss(Guid id,[FromBody]Dictionary<string,string?> input,CancellationToken ct){if(!UserId(out var userId))return Unauthorized();try{return await service.MissAsync(id,input.GetValueOrDefault("reason"),userId,ct)?NoContent():NotFound();}catch(InvalidOperationException ex){return Conflict(new{message=ex.Message});}}}
